(()=>{
  const C=Cimora,{S,M,E,ui,btn,link,art,money,path}=C;
  const current=()=>C.ctx();
  const repaint=()=>{const y=window.scrollY;S.render();window.scrollTo(0,y);};
  const modal=(t,b,f='',wide=false)=>S.modal(t,b,f,wide);
  const nodeById=(e,id)=>e.graph.nodes.find(n=>n.id===id);
  const safe=()=>{const c=current();if(c?.e.run&&['running','paused'].includes(c.e.run.status)){S.toast('请先停止当前制作批次，再修改工程输入；暂停时仍保留原输入快照。');return false;}return true;};
  function showPlan(target='all',force=false){const c=current(),proposal=M.plan(c.e,target,force);ui.proposal=proposal;modal('确认这一次制作',`<p>只执行所选步骤及其未完成依赖。成功结果保留，候选需要主动采用。</p><div class="cm-plan-list">${proposal.ids.map(k=>{const n=nodeById(c.e,k);return `<div><span>${E(n.title)} <small>${E(n.provider)}</small></span><b>${money(n.cost)}</b></div>`;}).join('')||'<p>当前版本已经就绪，无需重复生成。</p>'}</div><div class="cm-plan-total"><strong>本次预估 ${money(proposal.cost)}</strong><span>本章剩余 ${money(proposal.remaining)}</span></div>${proposal.cost>proposal.remaining?'<div class="cm-notice warning">超过剩余预算。调整范围或预算后再继续。</div>':''}<p class="cm-help">供应商为 API 能力分类示意，不承诺具体模型效果或报价。本机模拟不会提交请求，不扣除市场积分。</p>`,btn('调整预算','budget','cm-button ghost')+btn('确认并开始模拟','confirm-run','cm-button primary',proposal.ids.length&&proposal.cost<=proposal.remaining?'':'disabled'));
  }
  function nodeDetail(nid){const c=current(),n=nodeById(c.e,nid);if(!n)return;modal(n.title+' · 版本与任务',`<div class="cm-node-detail-preview">${art(({cast:1,world:0,prop:3,motion:6,sketch:6,final:8})[n.kind]||0,n.title)}</div><div class="cm-detail-lines"><span>状态<b>${n.status}</b></span><span>候选版本<b>v${n.version}</b></span><span>已采用版本<b>v${n.adopted}</b></span><span>能力路由<b>${E(n.provider)}</b></span><span>单次示例费用<b>${money(n.cost)}</b></span><span>成功执行次数<b>${n.attempts||0}</b></span></div><p>候选使用预置示例画面表达版本变化。旧采用版本和稳定运镜继续保留。</p>${n.lastInputVersions?`<details><summary>本次输入版本快照</summary><pre>${E(JSON.stringify(n.lastInputVersions,null,2))}</pre></details>`:''}`,btn('查看影响范围','node-impact','cm-button ghost',`data-node="${nid}"`)+btn(n.status==='failed'?'重试失败步骤':'生成新候选','run-node','cm-button ghost',`data-node="${nid}"`)+(n.status==='done'&&n.version>n.adopted?btn('采用当前候选','adopt-node','cm-button primary',`data-node="${nid}"`):''));}
  function storyCandidate(kind){const c=current(),input=c.e.scriptDraft??c.e.script;textCandidate(input,kind,txt=>{ui.pendingStory=txt;});}
  function textCandidate(input,kind,store){const text=M.generateStory(input,'细腻治愈',kind);store(text);modal(kind==='polish'?'润色候选 · 原文保留':'故事扩写候选',`<p>你可以直接修改候选。采用后将显示分镜和图片的影响范围。</p><textarea id="cm-story-candidate" rows="14" class="cm-candidate-text">${E(text)}</textarea><small class="cm-help">本机文本结构示例，不代表真实模型输出。</small>`,btn('保留原文','close-cm','cm-button ghost')+btn('采用这份候选','adopt-story','cm-button primary'),true);}
  function seedAssets(c){const specs=[['角色','主人公 · 身份参考',1,'锁定发型、面部特征与主要服装。'],['角色','重逢的人 · 身份参考',2,'保留人物身份与服装约束。'],['场景','故事发生的地方',0,'保持空间结构、光线和季节一致。'],['道具','推动剧情的信物',3,'记录外观、持有者与剧情状态。'],['画风','雨日电影感',8,'细腻二次元线条，灰蓝与暖金光。']];if(M.output(c.p)!=='comic')specs.push(['声音','主人公 · 预置音色',1,'声音参数示意，无音色克隆。'],['表情姿势','主人公 · 情绪参考',8,'平静、犹豫、微笑等参考。'],['分层资料','场景层级建议',0,'前景、中景、背景与遮挡补画建议。']);for(const [type,name,idx,desc]of specs){let a=S.state.assets.find(a=>a.projectId===c.p.id&&a.name===name);if(!a){a={id:S.id('asset'),name,type,art:idx,desc,version:1,locked:false,projectId:c.p.id,chapterIds:[c.c.id]};S.state.assets.push(a);}c.p.assetIds??=[];if(!c.p.assetIds.includes(a.id))c.p.assetIds.push(a.id);c.e.bindings[a.id]=a.version;}M.log(c.e,'提取本章资产草案',`${specs.length} 项，需确认并锁定；不调用模型`);repaint();S.toast('已建立本章资产草案与版本引用。');}
  function assetImpact(a){const refs=S.state.projects.flatMap(p=>[...p.chapters,...(p.episodes||[])].map(c=>({p,c,e:M.ensure(p,c)}))).filter(c=>c.e.bindings[a.id]);modal('资产版本与影响范围',`<h3>${E(a.name)} · 当前 v${a.version}</h3><p>以下章节引用固定版本。同步只标记相关制作步骤，已有画面不被覆盖。</p>${refs.map(c=>`<div class="cm-candidate-row"><span>${E(c.p.name)} / ${E(c.c.title)}<small>引用 v${c.e.bindings[a.id]} → 当前 v${a.version}</small></span>${btn('同步此章引用','sync-asset','cm-button ghost small',`data-id="${a.id}" data-project="${c.p.id}" data-chapter="${c.c.id}"`)}</div>`).join('')||'<p>尚未被任何章节引用。</p>'}`,link('查看资产详情','/app/assets/'+a.id,'cm-button primary'));}
  function publish(){const c=current();modal('发布作品快照',`<form data-cm-form="publish-work"><label class="cm-label">作品标题<input name="title" required value="${E(c.p.name)}" maxlength="60"></label><p>${E(c.c.title)} · ${c.e.boards.length} 分格</p><div class="cm-notice">只保存本机作品快照，不发布到互联网。后续项目修改不会改变已发布快照。源工程与资产不随作品公开。</div><button class="cm-button primary full">创建作品快照</button></form>`);}
  async function exportComic(c){const w=Number(S.$('#cm-comic-width')?.value||1080),gap=c.e.comicGap||20,panels=c.e.boards,h=170+panels.length*(w*1+gap)+70,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const g=canvas.getContext('2d');g.fillStyle='#f4eee8';g.fillRect(0,0,w,h);g.textAlign='center';g.fillStyle='#242237';g.font='bold 42px sans-serif';g.fillText(c.p.name,w/2,66,w-60);g.font='24px sans-serif';g.fillText(c.c.title,w/2,112,w-60);let y=170;for(const b of panels){const im=new Image();im.src=Art.url(b.art);await im.decode();g.drawImage(im,24,y,w-48,w-48);g.fillStyle='#f4eee8';g.fillRect(24,y+w-150,w-48,102);g.fillStyle='#302a40';g.font='26px sans-serif';g.fillText(b.dialogue,w/2,y+w-90,w-90);y+=w+gap;}canvas.toBlob(blob=>{if(!blob)return;S.state.exports.unshift({id:S.id('export'),projectId:c.p.id,name:c.p.name+' · '+c.c.title,kind:'PNG',status:'完成',size:w+' × '+canvas.height,date:'刚刚'});M.save();S.download(blob,'cimora-'+c.p.id+'-'+c.c.id+'.png');},'image/png');}
  function handle(action,el){const c=current(),e=c?.e,nid=el.dataset.node;
    switch(action){
      case'mobile-menu':S.$('.cm-shell')?.classList.toggle('menu-open');return;
      case'close-cm':S.close();return;
      case'set-view':e.view=el.dataset.view;M.save();S.route(path(c,e.stage,e.view));return;
      case'new-source':M.db.newDraft.source=el.dataset.source;M.save();repaint();return;
      case'new-view':M.db.newDraft.view=el.dataset.view;M.save();repaint();return;
      case'sample-idea':M.db.newDraft.text='一个女孩回到阔别七年的旧书店，与一直记得她的人重逢。她口袋里藏着一封没有寄出的信。';M.db.newDraft.name||='雨停之后的来信';M.save();repaint();return;
      case'new-expand':case'new-polish':{const d=M.db.newDraft;if(d.text.trim().length<5){S.toast('先写一句故事，或使用示例灵感。');return;}d.candidate=M.generateStory(d.text,d.tone,action==='new-polish'?'polish':'expand');d.candidateKind=action;M.save();repaint();S.toast('故事候选已就绪，可以直接修改。');return;}
      case'story-direction':{const d=M.db.newDraft;d.direction=+el.dataset.index;d.tone=['细腻治愈','悬疑反转','奇幻冒险'][d.direction];if(d.text.trim())d.candidate=M.generateStory(d.text,d.tone);M.save();repaint();return;}
      case'create-cimora-project':case'create-blank-project':{const d=M.db.newDraft;if(action!=='create-blank-project'&&d.text.trim().length<5&&!d.candidate){S.toast('先写一句故事，或选择从空白画布开始。');return;}const cc=M.create({name:d.name||'我的新故事',text:d.candidate||d.text,source:d.source,output:d.output,view:action==='create-blank-project'?'canvas':d.view,blank:action==='create-blank-project',genre:d.tone});cc.e.original=d.text;M.db.newDraft=null;M.save();S.route(path(cc,'story',cc.e.view));S.toast('工程已创建，故事与原始输入分别保留。');return;}
      case'story-expand':case'story-polish':storyCandidate(action==='story-polish'?'polish':'expand');return;
      case'adopt-story':if(!safe())return;{const txt=S.$('#cm-story-candidate').value;M.change(e,'story','采用故事候选');e.script=txt;delete e.scriptDraft;M.save();S.close();repaint();S.toast('故事已采用，下游已标记更新，旧画面保留。');return;}
      case'confirm-script':if(!safe())return;{const txt=S.$('#cm-story-text').value;if(txt.trim().length<5){S.toast('请先写一句完整的故事。');return;}const changes=M.change(e,'story','确认故事新版本');e.script=txt;delete e.scriptDraft;c.c.status='分镜待确认';M.save();S.navigationScriptSaved?.();modal('故事已保存',`<p>已保存新的故事版本，${changes.length} 个下游步骤需要复核。已有分镜、候选与采用版本继续保留。</p>`,link('继续拆分分镜 →',path(c,'boards'),'cm-button primary')+btn('查看关系画布','set-view','cm-button ghost','data-view="canvas"'));return;}
      case'story-history':modal('故事历史',`${e.history.filter(h=>h.node==='story').map(h=>`<section class="cm-history-item"><strong>v${h.version} · ${new Date(h.time).toLocaleString('zh-CN')}</strong><p>${E(h.script.slice(0,180))}</p>${btn('恢复为新版本','restore-story','cm-button ghost small',`data-id="${h.id}"`)}</section>`).join('')||'<p>确认修改后会保存此前的故事。原始输入也一直保留。</p>'}<details><summary>最初输入</summary><p>${E(e.original||c.p.text||'从空白开始')}</p></details>`);return;
      case'restore-story':if(!safe())return;{const old=e.history.find(h=>h.id===el.dataset.id);if(!old)return;const txt=old.script;M.change(e,'story','从历史恢复为新版本');e.script=txt;M.save();S.close();repaint();return;}
      case'split-chapters':if(!safe())return;{const matches=[...e.script.matchAll(/【第[一二三四五六七八九十\d]+章\s*[·：:]?\s*([^】]+)】\s*([\s\S]*?)(?=【|$)/g)];ui.chapterSuggestions=matches.length?matches.map(m=>({title:m[1].trim(),script:m[2].trim()})):[{title:'故事的开始',script:e.script},{title:'目标与冲突',script:'明确人物的目标，让意外事件阻碍目标，并给出新的线索。'},{title:'选择与回应',script:'让人物作出选择，回应前文的线索，并留下下一章的钩子。'}];modal('从故事生成章节建议',`<p>当前章保留。以下按故事章节标题提取，每章分别保存对应内容；没有章节标题时提供结构建议。</p><ol class="cm-template-steps">${ui.chapterSuggestions.map(ch=>`<li><strong>${E(ch.title)}</strong><p>${E(ch.script.slice(0,140))}</p></li>`).join('')}</ol>`,btn('保留现有章节','close-cm','cm-button ghost')+btn('添加缺少的章节','confirm-chapters','cm-button primary'));return;}
      case'confirm-chapters':for(const suggestion of ui.chapterSuggestions||[]){if(c.p.chapters.some(ch=>ch.title===suggestion.title))continue;const ch={id:S.id('chapter'),title:suggestion.title,status:'故事草稿',seconds:0};c.p.chapters.push(ch);const ce=M.ensure(c.p,ch);ce.script=suggestion.script;ce.original=e.original;for(const n of ce.graph.nodes){n.status=n.kind==='story'?'done':'idle';n.version=n.kind==='story'?1:0;n.adopted=n.version;}}M.log(e,'采用章节大纲','保留当前章，各章节分别保存提取后的故事内容');S.close();repaint();return;
      case'add-chapter':modal('添加章节',`<form data-cm-form="add-chapter"><label class="cm-label">章节名称<input name="title" required maxlength="60" placeholder="下一章，会发生什么？"></label><button class="cm-button primary full">建立章节工程</button></form>`);return;
      case'add-board':if(!safe())return;if(e.boards.length>=20){S.toast('原型最多展示 20 个分格。');return;}M.change(e,'boards','新增分格');e.boards.push({id:S.id('panel'),title:'新的情节',shot:'中景',action:'描述这一格里的动作。',dialogue:'在这里写对白。',art:0,version:1,approved:false});M.save();repaint();return;
      case'edit-board':{ui.selectedBoard=+el.dataset.index;const b=e.boards[ui.selectedBoard];modal('编辑第 '+(ui.selectedBoard+1)+' 格',`<form data-cm-form="edit-board"><div class="cm-board-edit-preview">${art(b.art,b.title)}</div><label class="cm-label">分格标题<input name="title" value="${E(b.title)}" required maxlength="60"></label><label class="cm-label">画面动作<textarea name="action" rows="3">${E(b.action)}</textarea></label><label class="cm-label">对白<input name="dialogue" value="${E(b.dialogue)}" maxlength="200"></label><label class="cm-label">景别<select name="shot">${['远景','中景','人物特写','道具特写','双人中景'].map(t=>`<option ${b.shot===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="cm-button primary full">保存为新版本</button></form>`,btn('使用局部创作工具','context-tool','cm-button ghost','data-kind="panel"'));return;}
      case'move-board':case'duplicate-board':if(!safe())return;{const i=+el.dataset.index;M.change(e,'boards','调整分格结构');if(action==='move-board'){const j=i+Number(el.dataset.dir);if(j<0||j>=e.boards.length)return;[e.boards[i],e.boards[j]]=[e.boards[j],e.boards[i]];}else{if(e.boards.length>=20)return;const b=M.clone(e.boards[i]);b.id=S.id('panel');b.title+=' · 副格';e.boards.splice(i+1,0,b);}M.save();repaint();return;}
      case'approve-board':if(!safe())return;e.boards[+el.dataset.index].approved=!e.boards[+el.dataset.index].approved;M.save();repaint();return;
      case'focus-panel':ui.selectedBoard=+el.dataset.index;repaint();S.$('#cm-panel-'+ui.selectedBoard)?.scrollIntoView({block:'center',behavior:'smooth'});return;
      case'select-shot':ui.selectedBoard=+el.dataset.index;repaint();return;
      case'toggle-preview':e.previewPlaying=!e.previewPlaying;M.save();repaint();return;
      case'split-shot':if(!safe())return;e.boards[ui.selectedBoard].extraShot=!e.boards[ui.selectedBoard].extraShot;M.change(e,'shots','修改分格与镜头映射');repaint();return;
      case'shot-mapping':modal('分格与镜头映射',e.boards.map((b,i)=>`<div class="cm-candidate-row"><span>分格 ${i+1} · ${E(b.title)}</span><b>镜头 ${i+1}${b.extraShot?'A + '+(i+1)+'B':''}</b></div>`).join('')+'<p>选中镜头后可以拆成两个；镜头参数和表演备注可在当前页面编辑，与分格共用同一份章节数据。</p>');return;
      case'stable-fallback':{const n=e.graph.nodes.find(n=>n.kind==='motion');if(n)n.useStable=true;M.log(e,'回退稳定底稿','增强候选仍保留在版本记录中');S.close();repaint();return;}
      case'enable-motion':if(!safe())return;{c.p.outputType='both';for(const ch of c.p.chapters){const ce=M.ensure(c.p,ch),existing=new Set(ce.graph.nodes.map(n=>n.kind));for(const kind of ['shots','voice','motion'])if(!existing.has(kind)){const def=M.defs[kind];ce.graph.nodes.push({id:kind,kind,title:def[0],x:kind==='shots'?1300:1610,y:kind==='voice'?650:400,status:'idle',version:0,adopted:0,cost:def[3],provider:def[4],attempts:0});}for(const [from,to] of [['sketch','shots'],['shots','voice'],['shots','motion'],['cast','motion'],['world','motion'],['motion','review'],['voice','review']])if(!ce.graph.edges.some(x=>x.from===from&&x.to===to))ce.graph.edges.push({from,to});}M.save();S.route(path(c,'motion'));return;}
      case'shot-edit':{const b=e.boards[ui.selectedBoard];modal('镜头 '+(ui.selectedBoard+1)+' · 表演与时间',`<form data-cm-form="shot-edit"><div class="cm-board-edit-preview">${art(b.art,b.title)}</div><label class="cm-label">镜头时长（秒）<input name="duration" type="number" min="2" max="12" step="0.5" value="${b.duration||5}" required></label><label class="cm-label">运镜<select name="motion">${['缓慢推进','横向摇移','缓慢拉远','固定镜头'].map(t=>`<option ${(b.motion||'缓慢推进')===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="cm-label">镜头对白<textarea name="dialogue" rows="2" maxlength="200">${E(b.dialogue)}</textarea></label><label class="cm-label">表演与图层备注<textarea name="direction" rows="3" maxlength="500" placeholder="例如：人物微微转头，保留前景雨滴；本原型仅保存参数。">${E(b.direction||'')}</textarea></label><p class="cm-help">保存到当前章节。对白同步分格，镜头参数进入下游版本检查；预览仅示意运镜。</p><button class="cm-button primary full">保存镜头新版本</button></form>`);return;}
      case'seed-assets':if(safe())seedAssets(c);return;
      case'asset-category':ui.assetType=el.dataset.type;ui.assetScope='project';S.route('/app/assets');return;
      case'asset-scope':ui.assetScope=el.dataset.scope;repaint();return;
      case'library-type':ui.assetType=el.dataset.type;repaint();return;
      case'asset-detail':S.route('/app/assets/'+el.dataset.id);return;
      case'pick-asset':modal('引用资产到本章',`<p>${E(c.p.name)} / ${E(c.c.title)} · 引用固定版本，不复制文件。</p><div class="cm-pick-list">${S.state.assets.filter(a=>!a.projectId||a.projectId===c.p.id).map(a=>btn(`${art(a.art)}<span><strong>${E(a.name)}</strong><small>${E(a.type)} / v${a.version}</small></span>`,'bind-asset','cm-pick-item',`data-id="${a.id}"`)).join('')}</div>`);return;
      case'bind-asset':if(!safe())return;{const a=S.state.assets.find(a=>a.id===el.dataset.id);e.bindings[a.id]=a.version;c.p.assetIds??=[];if(!c.p.assetIds.includes(a.id))c.p.assetIds.push(a.id);M.log(e,'引用资产',`${a.name} v${a.version}`);S.close();repaint();S.toast('已引用到当前章节，固定使用此版本。');return;}
      case'asset-impact':assetImpact(S.state.assets.find(a=>a.id===el.dataset.id));return;
      case'asset-revise':{const a=S.state.assets.find(a=>a.id===el.dataset.id);modal('创建资产新版本',`<form data-cm-form="asset-version" data-id="${a.id}"><p>已有引用继续使用旧版。新版本需要主动同步。</p><label class="cm-label">新的身份与视觉约束<textarea name="desc" required rows="5">${E(a.desc)}</textarea></label><button class="cm-button primary full">保存新版本草稿</button></form>`);return;}
      case'cm-lock-asset':S.state.assets.find(a=>a.id===el.dataset.id).locked=true;M.save();repaint();return;
      case'sync-asset':{const a=S.state.assets.find(a=>a.id===el.dataset.id),cc=M.context(el.dataset.project,el.dataset.chapter);if(cc.e.run&&['running','paused'].includes(cc.e.run.status)){S.toast('请先停止该章节运行，再同步资产。');return;}if(cc.e.bindings[a.id]===a.version){S.toast('此章已经引用当前版本。');return;}cc.e.bindings[a.id]=a.version;M.change(cc.e,a.type==='场景'?'world':a.type==='道具'||a.type==='服装'?'prop':'cast','同步资产版本引用');M.save();S.close();repaint();S.toast('引用已更新，下游待同步，旧画面保留。');return;}
      case'new-asset':modal('创建本章资产',`<form data-cm-form="new-asset"><label class="cm-label">资产名称<input name="name" required maxlength="60"></label><label class="cm-label">资产类型<select name="type">${['角色','场景','道具','服装','画风','人物音色','背景音乐','环境声','动作音效','表情姿势'].map(t=>'<option>'+t+'</option>').join('')}</select></label><label class="cm-label">描述与约束<textarea name="desc" rows="4" required></textarea></label><label class="cm-label">归属<select name="scope"><option value="chapter">当前章节</option><option value="project">当前项目</option><option value="studio">工作室通用</option></select></label><button class="cm-button primary full">保存资产草稿</button></form>`);return;
      case'context-tool':ui.toolContext={project:c.p.id,chapter:c.c.id,index:ui.selectedBoard,kind:el.dataset.kind||'panel'};modal('为当前内容选择工具',`<p>${E(c.p.name)} / ${E(c.c.title)} / 第 ${ui.selectedBoard+1} 格</p><div class="cm-context-tool-list">${FrameData.tools.filter(t=>!t.hidden).filter(t=>['oc-sheet','expressions','colorize','lettering','comic-to-motion'].includes(t.id)).map(t=>link(`<span>${t.icon}</span><div><strong>${t.title}</strong><small>${t.desc}</small></div>↗`,'/app/tools/'+t.id,'')).join('')}</div>`);return;
      case'apply-tool-result':{const r=S.state.results[el.dataset.id],tc=ui.toolContext;if(!r||r.status!=='ready'){S.toast('先生成工具示例结果，再带回原分格。');return;}if(!tc)return;const cc=M.activate(tc.project,tc.chapter),b=cc.e.boards[tc.index];if(!b){S.toast('原分格已移除，请重新选择。');return;}M.change(cc.e,'boards','采用工具结果示例');b.toolResult={id:el.dataset.id,generatedAt:r.generatedAt};if(el.dataset.id==='lettering'&&r.translated)b.dialogue=r.translated;b.version++;M.save();ui.toolContext=false;S.route(path(cc,'boards','flow'));S.toast('工具来源和参数已关联回原分格；图像仍为预置示例。');return;}
      case'run-plan':showPlan();return;
      case'run-node':showPlan(nid,true);return;
      case'confirm-run':{const err=M.begin(e,ui.proposal);if(err){S.toast(err);return;}S.close();repaint();S.toast('模拟任务已入队；可以继续查看工程。');return;}
      case'pause-run':if(e.run)e.run.status='paused';M.log(e,'暂停制作批次','保留当前进度，未提交新的任务');repaint();return;
      case'resume-run':if(e.run)e.run.status='running';M.save();repaint();return;
      case'cancel-run':if(e.run){e.run.status='cancelled';for(const n of e.graph.nodes.filter(n=>['queued','running'].includes(n.status)))n.status=n.version?'stale':'idle';M.log(e,'停止制作批次','已完成结果保留，后续任务未执行');}repaint();return;
      case'retry-run':showPlan();return;
      case'budget':modal('本章预算与执行限制',`<form data-cm-form="budget"><p>当前已用 ${money(e.spent)}。预算控制模型任务，不影响已有作品与市场积分。</p><label class="cm-label">本章预算 / USD 示例<input name="budget" type="number" step="0.01" min="${e.spent}" max="100" value="${e.budget}" required></label><button class="cm-button primary full">保存预算</button></form>`);return;
      case'node-detail':nodeDetail(nid);return;
      case'adopt-node':M.adopt(e,nid);{const n=nodeById(e,nid);if(n?.kind==='motion')n.useStable=false;}S.close();repaint();S.toast('候选已采用，此前版本仍有记录。');return;
      case'select-node':e.selected=nid;M.save();repaint();return;
      case'node-edit':{const n=nodeById(e,nid),stage=({story:'story',cast:'assets',world:'assets',prop:'assets',boards:'boards',sketch:'boards',final:'boards',layout:'comic',shots:'motion',motion:'motion',voice:'audio',review:'review',export:'review'})[n.kind];e.view='flow';M.save();S.route(path(c,stage,'flow'));return;}
      case'node-impact':{const n=nodeById(e,nid),kids=M.descendants(e,nid);modal('变更影响范围',`<h3>${E(n.title)}</h3><p>修改此内容后，以下 ${kids.length} 个步骤需要复核。旧采用版本与稳定底稿继续保留。</p><div class="cm-plan-list">${kids.map(k=>`<div><span>${E(nodeById(e,k).title)}</span><small>${nodeById(e,k).status==='done'?'将标记来源更新':'待制作'}</small></div>`).join('')}</div>`,btn('回到创作','close-cm','cm-button primary'));return;}
      case'link-from':if(!safe())return;ui.canvasLink=nid;S.toast('点击目标节点左侧圆点建立关联。');repaint();return;
      case'link-to':if(!safe())return;if(!ui.canvasLink){S.toast('先点击来源节点右侧圆点。');return;}{const err=M.connect(e,ui.canvasLink,nid);if(err){S.toast(err);return;}ui.canvasLink=null;repaint();return;}
      case'cancel-link':ui.canvasLink=null;repaint();return;
      case'unlink':if(!safe())return;e.graph.edges=e.graph.edges.filter(x=>x.from!==el.dataset.from||x.to!==el.dataset.to);M.log(e,'移除制作依赖',`${el.dataset.from} → ${el.dataset.to}`);repaint();return;
      case'add-node':modal('添加创作分支',`<div class="cm-add-node-list">${Object.keys(M.defs).filter(k=>M.output(c.p)!=='comic'||!['shots','voice','motion'].includes(k)).map(k=>btn(`<span>${M.defs[k][1]}</span>${M.defs[k][0]}`,'confirm-add-node','cm-button ghost',`data-kind="${k}"`)).join('')}</div><p>添加后从两侧圆点连接输入。节点仅加入当前章节。</p>`);return;
      case'confirm-add-node':if(!safe())return;e.selected=M.addNode(e,el.dataset.kind);S.close();repaint();return;
      case'delete-node':if(!safe())return;e.graph.nodes=e.graph.nodes.filter(n=>n.id!==nid);e.graph.edges=e.graph.edges.filter(x=>x.from!==nid&&x.to!==nid);e.selected=e.graph.nodes[0]?.id;M.save();repaint();return;
      case'auto-layout':if(!safe())return;{const depth=new Map(),walk=k=>{if(depth.has(k))return depth.get(k);const ps=e.graph.edges.filter(x=>x.to===k);const d=ps.length?Math.max(...ps.map(x=>walk(x.from)))+1:0;depth.set(k,d);return d;},rows={};e.graph.nodes.forEach(n=>{const d=walk(n.id);rows[d]??=0;n.x=60+d*310;n.y=70+rows[d]++*245;});M.save();repaint();return;}
      case'fit-canvas':{const root=S.$('#cm-canvas-viewport');const max=Math.max(...e.graph.nodes.map(n=>n.x+260));e.graph.viewport={x:20,y:30,zoom:Math.max(.22,Math.min(.8,(root.clientWidth-45)/max))};C.canvasTransform(c);M.save();return;}
      case'zoom-in':case'zoom-out':e.graph.viewport.zoom=Math.max(.22,Math.min(1.6,e.graph.viewport.zoom+(action==='zoom-in'?.08:-.08)));C.canvasTransform(c);M.save();return;
      case'show-events':modal('本章工程事件',e.events.map(ev=>`<div class="cm-history-item"><strong>${E(ev.text)}</strong><p>${E(ev.detail)}</p><small>${new Date(ev.time).toLocaleString('zh-CN')}</small></div>`).join('')||'<p>还没有制作记录。</p>','',true);return;
      case'comic-export':exportComic(c).catch(()=>S.toast('图片合成失败，请刷新后重试。'));return;
      case'export-project':S.download({brand:'Cimora',prototype:true,project:c.p,chapter:c.c,engineering:e,notice:'工程与采用版本说明，不包含真实视频和 API 结果'},'cimora-project-'+c.p.id+'.json');return;
      case'deliver-motion':if(!e.reviewChecks?.every(Boolean)||e.reviewChecks.length<3){S.toast('先完成三项审查。');return;}if(e.graph.nodes.some(n=>n.version>n.adopted)){S.toast('还有新候选未采用，请先确认版本。');return;}S.state.exports.unshift({id:S.id('delivery'),projectId:c.p.id,name:c.p.name+' · '+c.c.title,kind:'MP4',status:'演示完成',size:'无真实视频文件',date:'刚刚'});M.log(e,'创建模拟交付快照','版本已冻结，不生成真实 MP4');modal('交付流程演示完成',`<h3>${E(c.p.name)} / ${E(c.c.title)}</h3><p>已记录本次采用版本、成本与工程信息。当前原型未编码视频，可下载工程 JSON 或发布本机作品快照。</p>`,btn('下载工程说明','export-project','cm-button ghost')+btn('发布作品快照','publish-work','cm-button primary'));return;
      case'publish-work':publish();return;
      case'favorite-work':{const i=M.db.favorites.indexOf(el.dataset.id);if(i>=0)M.db.favorites.splice(i,1);else M.db.favorites.push(el.dataset.id);M.save();repaint();return;}
      case'gallery-filter':ui.galleryType=el.dataset.type;repaint();return;
      case'work-view':S.$('#cm-work-reader').classList.toggle('motion',el.dataset.view==='motion');S.$$('.cm-work-detail [data-cm="work-view"]').forEach(b=>b.classList.toggle('primary',b===el));return;
      case'market-filter':ui.marketType=el.dataset.type;repaint();return;
      case'buy-market':{const it=C.catalog().find(it=>it.id===el.dataset.id);modal('确认加入资源库',`<h3>${E(it.title)}</h3><p>${it.type} / ${it.price?it.price+' 积分':'免费'} · 当前可用 ${M.db.wallet} 积分</p><p>这是资源使用许可的模拟购买。后续模型运行费用另外预估，不包含在购买积分内。</p>`,btn('返回','close-cm','cm-button ghost')+btn('确认'+(it.price?'使用积分':'免费领取'),'confirm-buy-market','cm-button primary',`data-id="${it.id}"`));return;}
      case'confirm-buy-market':{const it=C.catalog().find(it=>it.id===el.dataset.id),err=M.purchase(it);if(err)S.toast(err);else S.toast('已加入资源库，积分账本已记录。');S.close();repaint();return;}
      case'use-market':{const it=C.catalog().find(it=>it.id===el.dataset.id);modal('使用到当前章节',`<h3>${E(it.title)}</h3><p>${E(c.p.name)} / ${E(c.c.title)}</p><p>${it.type==='模板'?'应用排版参数，保留原分格。':it.type==='技能'?'为本章增加可运行的技能分支。':'新增关联工作流分支，保留已有制作结果。'}</p>`,btn('确认使用','confirm-use-market','cm-button primary',`data-id="${it.id}"`));return;}
      case'confirm-use-market':if(!safe())return;{const it=C.catalog().find(it=>it.id===el.dataset.id);e.installed??=[];if(!e.installed.includes(it.id)){e.installed.push(it.id);if(it.type==='模板')e.comicGap=36;else{const k=M.addNode(e,it.type==='技能'?'story':'sketch'),n=nodeById(e,k);n.title=it.title;M.connect(e,'story',k);}}M.log(e,'应用创作者资源',it.title+' · 保留已有内容');S.close();S.route(path(c,it.type==='模板'&&M.output(c.p)!=='motion'?'comic':e.stage,it.type==='模板'?'flow':'canvas'));return;}
      case'creator-draft':modal('创建资源草稿',`<form data-cm-form="creator-draft"><label class="cm-label">名称<input name="title" required maxlength="60"></label><label class="cm-label">类型<select name="type"><option>技能</option><option>模板</option><option>工作流</option></select></label><label class="cm-label">输入与输出<input name="uses" required placeholder="例如：人物描述 → 对白润色候选"></label><label class="cm-label">资源说明<textarea name="desc" required rows="3"></textarea></label><label class="cm-label">积分价格<input name="price" type="number" min="0" max="1000" value="60" required></label><button class="cm-button primary full">保存草稿</button></form>`);return;
      case'publish-resource':{const it=M.db.drafts.find(d=>d.id===el.dataset.id);modal('预览并模拟上架',`<h3>${E(it.title)}</h3><p>${E(it.desc)}</p><p>输入与输出：${E(it.uses)}</p><p>${it.price} 积分 · 本机展示，不发生真实交易。</p><p>示例许可：可用于自己的作品，不允许原样转售。发布前请确认有权分享相关内容。</p>`,btn('确认本机上架','confirm-publish-resource','cm-button primary',`data-id="${it.id}"`));return;}
      case'confirm-publish-resource':M.db.drafts.find(d=>d.id===el.dataset.id).published=true;M.save();S.close();repaint();S.toast('资源已在本机市场展示，未发放上传奖励。');return;
      case'open-market':S.route('/app/market/'+el.dataset.id);return;
      case'show-archive':modal('归档项目',S.state.projects.filter(p=>p.archived).map(p=>`<div class="cm-candidate-row"><span>${E(p.name)}</span>${btn('恢复项目','restore-project-cm','cm-button ghost',`data-id="${p.id}"`)}</div>`).join('')||'<p>暂无归档项目。</p>');return;
      case'restore-project-cm':S.project(el.dataset.id).archived=false;M.save();S.close();repaint();return;
      case'speak-dialogue':if(!('speechSynthesis'in window)){S.toast('当前浏览器不支持系统语音。');return;}speechSynthesis.cancel();{const u=new SpeechSynthesisUtterance(e.boards[ui.selectedBoard]?.dialogue||'你好，这是对白试听。');u.lang='zh-CN';speechSynthesis.speak(u);}return;
      default:S.toast('请从当前页面选择一个创作操作。');
    }
  }
  document.addEventListener('click',ev=>{const el=ev.target.closest('[data-cm]');if(!el)return;ev.preventDefault();handle(el.dataset.cm,el);});
  document.addEventListener('input',ev=>{const el=ev.target,k=el.dataset.cmInput,c=current();if(!k)return;const d=M.db.newDraft;
    if(k.startsWith('new-')&&d)d[{ 'new-name':'name','new-text':'text','new-candidate':'candidate'}[k]]=el.value;
    if(k==='script')c.e.scriptDraft=el.value;
    if(k==='asset-search'){ui.assetSearch=el.value;S.$('#cm-library-grid').innerHTML=C.assetList();}
    if(k==='project-search'){ui.projectSearch=el.value;S.$('#cm-project-list').innerHTML=C.projectList();}
    if(k==='comic-gap'){c.e.comicGap=+el.value;S.$('.cm-long-comic').style.gap=el.value+'px';S.$('#cm-gap-label').textContent=el.value+'px';}
    if(k==='seek')S.$('#cm-seek-label').textContent=C.timecode(+el.value)+' / '+C.timecode(C.seconds(c.e))+' · 音轨布局示意';
    M.save();
  });
  document.addEventListener('change',ev=>{const el=ev.target,k=el.dataset.cmChange,c=current(),d=M.db.newDraft;if(!k)return;
    if(k==='scope-project'){const cc=M.activate(el.value);const section=S.context.parts[1];if(['create','canvas'].includes(section))S.route(path(cc,cc.e.stage,cc.e.view));else if(['runs'].includes(section))S.route(`/app/runs/${cc.p.id}/${cc.c.id}`);else repaint();return;}
    if(k==='scope-chapter'){const cc=M.activate(c.p.id,el.value);const section=S.context.parts[1];if(['create','canvas'].includes(section))S.route(path(cc,cc.e.stage,cc.e.view));else if(section==='runs')S.route(`/app/runs/${cc.p.id}/${cc.c.id}`);else repaint();return;}
    if(k==='new-tone')d.tone=el.value;if(k==='new-output')d.output=el.value;
    if(k==='shot-motion'){if(!safe()){repaint();return;}c.e.boards[ui.selectedBoard].motion=el.value;M.change(c.e,'shots','修改镜头运镜');}
    if(k==='voice-enabled'){if(!safe()){repaint();return;}c.e.voiceEnabled=el.checked;M.log(c.e,'切换配音分支',el.checked?'有声版本':'无声版本，运行时跳过语音任务');}
    if(k==='voice-style')c.e.voiceStyle=el.value;if(k==='music-style')c.e.musicStyle=el.value;
    if(k==='review-check'){c.e.reviewChecks??=[false,false,false];c.e.reviewChecks[+el.dataset.index]=el.checked;}
    if(k==='concurrency')c.e.concurrency=+el.value;if(k==='fail-demo')c.e.failDemo=el.checked;
    M.save();
  });
  document.addEventListener('submit',ev=>{const f=ev.target.closest('form[data-cm-form]');if(!f)return;ev.preventDefault();const v=Object.fromEntries(new FormData(f)),c=current(),e=c.e;switch(f.dataset.cmForm){
    case'add-chapter':{const ch={id:S.id('chapter'),title:v.title,status:'故事草稿',seconds:0};c.p.chapters.push(ch);M.ensure(c.p,ch);M.activate(c.p.id,ch.id);S.navigationSaved?.(f,true);S.close();S.route(path({p:c.p,c:ch,e:M.ensure(c.p,ch)},'story'));break;}
    case'edit-board':if(!safe())return;{M.change(e,'boards','保存分格新版本');const b=e.boards[ui.selectedBoard];Object.assign(b,v,{version:b.version+1,approved:false});M.save();S.navigationSaved?.(f,true);S.close();repaint();break;}
    case'shot-edit':if(!safe())return;{const b=e.boards[ui.selectedBoard];if(b.dialogue!==v.dialogue)M.change(e,'boards','修改镜头对白');M.change(e,'shots','保存镜头参数');Object.assign(b,v,{duration:Math.max(2,Math.min(12,+v.duration)),version:b.version+1});M.save();S.navigationSaved?.(f,true);S.close();repaint();S.toast('镜头参数已保存，分格和剪辑时间线同步更新。');break;}
    case'new-asset':{const a={id:S.id('asset'),name:v.name,type:v.type,desc:v.desc,art:v.type==='场景'?0:v.type==='道具'?3:1,version:1,locked:false,projectId:v.scope==='studio'?null:c.p.id,chapterIds:v.scope==='chapter'?[c.c.id]:[]};S.state.assets.push(a);if(v.scope!=='studio'){c.p.assetIds??=[];c.p.assetIds.push(a.id);}if(v.scope==='chapter')e.bindings[a.id]=1;M.save();S.navigationSaved?.(f,true);S.close();repaint();break;}
    case'asset-version':{const a=S.state.assets.find(a=>a.id===f.dataset.id);a.history??=[];a.history.push({version:a.version,desc:a.desc});a.version++;a.desc=v.desc;a.locked=false;M.save();S.navigationSaved?.(f,true);S.close();repaint();S.toast('新版本已保存，旧引用继续保留。');break;}
    case'budget':e.budget=+v.budget;M.save();S.navigationSaved?.(f,true);S.close();repaint();break;
    case'publish-work':{const pub=M.publish(c,v.title);S.navigationSaved?.(f,true);S.close();S.route('/app/community/'+pub.id);S.toast('作品快照已创建，仅本机可见。');break;}
    case'creator-draft':M.db.drafts.push({id:S.id('resource'),...v,price:+v.price,category:'创作者分享',author:'我的工作室',art:6,steps:['读取选择的内容','按资源说明处理','保存结果候选'],published:false});M.save();S.navigationSaved?.(f,true);S.close();repaint();break;
  }});
  setInterval(()=>{let changed=false;for(const chapters of Object.values(M.db.projects))for(const e of Object.values(chapters))if(e.run?.status==='running'){M.tick(e);changed=true;}if(changed&&S.context.path.startsWith('/app')&&S.$('#site-modal').hidden&&!S.$('.cm-canvas-viewport.dragging')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))repaint();},900);
  C.handle=handle;C.repaint=repaint;C.showPlan=showPlan;
})();
